          "a": "آج امتِ مسلمہ اخلاقی زوال، سیاسی انتشار اور عسکری پسماندگی سے دوچار ہے۔ معاشرے میں برائیوں کو کھلے عام برداشت کیا جاتا ہے جس کا نتیجہ مختلف فتنوں اور زوال کی صورت میں نکل رہا ہے۔ مسلمانوں کو یاد رکھنا چاہیے کہ وہ مکہ کی مظلومیت سے اپنے اخلاق، اتحاد اور اطاعتِ رسول ﷺ کے بل بوتے پر ہی نکل کر دنیا کے امام بنے تھے۔ اگر آج بھی وہی کردار زندہ کر لیا جائے تو اللہ کی نصرت اور عزت دوبارہ حاصل ہو سکتی ہے۔"
