          "a": "اسلام نے جنگ اور مالِ غنیمت کے تصور کو یکسر بدل کر رکھ دیا۔ زمانہ جاہلیت میں جنگیں لوٹ مار، قبائلی عصبیت اور عورتوں و بچوں کو لونڈی غلام بنانے کے لیے لڑی جاتی تھیں اور سارا مال طاقتور سردار لوٹ لیتے تھے۔\n\nاسلامی عسکری اصلاحات:\n۱. جنگ کا مقصد صرف اللہ کے دین کی حفاظت اور فتنہ کا خاتمہ ہے۔\n۲. غنیمت کے مال میں سے ۲۰ فیصد ریاست کے بیت المال کو دیا جاتا ہے تاکہ یتیموں، مسکینوں، ناداروں اور مسافروں کی کفالت کی جا سکے، اور باقی ۸۰ فیصد جان ہتھیلی پر رکھ کر لڑنے والے عام مجاہدین میں برابری کی بنیاد پر تقسیم ہوتا ہے۔\n۳. یوں اسلام نے جنگ کو ذاتی مفاد کے بجائے ایک اجتماعی، عادلانہ اور اخلاقی فریضہ بنا دیا۔"
