    "pashtoTranslation": "د الانفال سورت ۴۹ نه تر ۵۸ آيتونه: پدې برخه کې د منافقانو طعنې چې ګواکې مسلمانان پخپل دين مغرور شوي رد شوې دي. د کافرانو د ساه اخيستلو په وخت کې د پرښتو لخوا د هغوی وهل، د آلِ فرعون او پخوانیو قومونو د هلاکېدو اسباب، د قومونو د عروج او زوال الهي قانون، او د هغو يهودانو غندنه چې پرله پسې تړونونه ماتوي بيان شول. همدا راز په جګړه کې داسې سزا ورکول چې نور ترې عبرت واخلي او د خيانت په وخت کې په ښکاره توګه د تړون ختمول فرض شول.",
