    "titleEn": "Theme 2: Love & Obedience to Allah & His Messenger (Khatam-un-Nabiyyin)",
    "titlePs": "دويمه موضوع: د الله او د هغه د رسول مينه او اطاعت (او ختم نبوت)",
    "author": "باب سوم: موضوعاتی مطالعہ — درسی نصاب",
    "authorInfo": "اس موضوع میں اللہ تعالیٰ کی محبت کا مفہوم، رسول اللہ ﷺ کی محبت کو ایمان کا تقاضا قرار دینا، اطاعتِ الٰہی و نبوی کا باہمی اٹوٹ تعلق، اور اسلامی عقائد کی بنیاد 'عقیدۂ ختمِ نبوت' کے قرآنی دلائل، احادیثِ نبویہ، اجماعِ امت اور جھوٹے مدعیانِ نبوت کے خلاف امت کے تاریخی کردار کا مفصل بیان ہے۔",
    "urduText": "موضوع ۲: اللہ تعالیٰ اور اس کے رسول ﷺ کی محبت و اطاعت (اور ختمِ نبوت)\n\n۱. اللہ تعالیٰ کی محبت و اطاعت:\nانسان کا خالق، مالک اور رازق صرف اللہ تعالیٰ ہے۔ اس کی بے پایاں نعمتوں کا فطری تقاضا ہے کہ انسان کے دل میں سب سے زیادہ محبت اللہ تعالیٰ ہی کے لیے ہو۔ قرآن کا ارشاد ہے: 'وَالَّذِينَ آمَنُوا أَشَدُّ حُبًّا لِّلَّهِ' (اور جو ایمان لائے وہ اللہ کی محبت میں سب سے زیادہ شدید ہیں)۔ اللہ کی سچی محبت کا تقاضا اس کے احکام کی کامل اطاعت اور اس کی نافرمانی سے بچنا ہے۔\n\n۲. رسول اللہ ﷺ کی محبت و اطاعت:\nرسول اللہ ﷺ سے محبت ایمان کا لازمی جزو ہے۔ آپ ﷺ نے فرمایا: 'تم میں سے کوئی شخص مومن نہیں ہو سکتا جب تک کہ میں اس کے نزدیک اس کے باپ، اس کی اولاد اور تمام انسانوں سے زیادہ محبوب نہ ہو جاؤں' (صحیح بخاری)۔\nاطاعتِ رسول درحقیقت اطاعتِ خداوندی کا واحد پیمانہ ہے:\n'مَّن يُطِعِ الرَّسُولَ فَقَدْ أَطَاعَ اللَّهَ' (جس نے رسول کی اطاعت کی اس نے درحقیقت اللہ کی اطاعت کی)۔ سنتِ نبوی پر عمل کیے بغیر اللہ کی رضا اور محبت کا حصول ناممکن ہے۔\n\n۳. عقیدۂ ختمِ نبوت (خاتم النبیین ﷺ):\n'عقیدۂ ختمِ نبوت' اسلام کا وہ بنیادی اور قطعی عقیدہ ہے جس پر دین کی عمارت کھڑی ہے۔ اس کا مطلب یہ ہے کہ حضرت محمد مصطفیٰ ﷺ اللہ تعالیٰ کے آخری نبی اور رسول ہیں۔ آپ ﷺ پر نبوت و رسالت کا سلسلہ ہمیشہ کے لیے مکمل ہو چکا ہے اور قیامت تک آپ ﷺ کے بعد نہ کوئی نیا نبی آ سکتا ہے اور نہ کسی کو نبوت مل سکتی ہے۔\n\nقرآنی دلیل:\nسورۃ الاحزاب کی آیت ۴۰ میں ارشادِ باری تعالیٰ ہے:\n'مَّا كَانَ مُحَمَّدٌ أَبَا أَحَدٍ مِّن رِّجَالِكُمْ وَلَٰكِن رَّسُولَ اللَّهِ وَخَاتَمَ النَّبِيِّينَ'\n(محمد ﷺ تمہارے مردوں میں سے کسی کے باپ نہیں ہیں لیکن وہ اللہ کے رسول اور خاتم النبیین یعنی تمام نبیوں کے سلسلے کو ختم کرنے والے ہیں)۔\n\nاحادیثِ نبویہ کے دلائل:\n۱. قصرِ نبوت کی مثال: آپ ﷺ نے فرمایا کہ میری اور انبیاء کی مثال ایک خوبصورت محل کی طرح ہے جس کے کونے میں ایک اینٹ کی جگہ خالی تھی، میں وہی آخری اینٹ ہوں اور میں خاتم النبیین ہوں (صحیح بخاری)۔\n۲. واضح اعلان: آپ ﷺ نے فرمایا: 'لَا نَبِيَّ بَعْدِي' (میرے بعد کوئی نبی نہیں ہے)۔\n\nاجماعِ امت اور تاریخ:\nنبی کریم ﷺ کے وصال کے فوراً بعد خلیفۂ اول حضرت ابو بکر صدیق رضی اللہ عنہ اور تمام صحابہ کرام نے نبوت کے جھوٹے دعویدار مسیلمہ کذاب کے خلاف جہاد کر کے اسے کیفرِ کردار تک پہنچایا۔ امتِ مسلمہ کا اس بات پر قطعی اجماع ہے کہ حضور ﷺ کے بعد جو کوئی نبوت کا دعویٰ کرے وہ دائرۂ اسلام سے خارج، کافر اور مرتد ہے۔",
